    return{...rendered,blob:new Blob(pieces,{type:'audio/wav'}),frames,leadingFrames,sourceStartSeconds:rendered.startSeconds,startSeconds:0,filename:safeFileName(p.projectName)+'-vocal-timeline.wav'};
