      await target.putLongWav(updated,{id:newId,blob:r.blob,hashes},baseline,guard);state.projects=state.projects.map(x=>x.projectId===id?updated:x);vocal.phase='saved';vocal.message='ç·¨é›†æ¸ˆã¿WAVã‚’åˆ¥éŸ³å£°ã¨ã—ã¦ä¿å­˜ã—ã¾ã—ãŸã€‚Mix / Masterã§é¸æŠžã§ãã¾ã™ã€‚';pcmOpen(id);return{ok:true,assetId:newId,project:updated};
